<?php
require '../config/koneksi.php';require '../includes/functions.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['delete_record'])){verify_csrf();$del=(int)($_POST['id']??0);$ds=$conn->prepare('DELETE FROM pendaftar WHERE id=?');$ds->bind_param('i',$del);$ds->execute();header('Location: index.php?msg=Data pendaftar berhasil dihapus');exit;}
$id=(int)($_GET['id']??0);$st=$conn->prepare("SELECT * FROM pendaftar WHERE id=?");$st->bind_param('i',$id);$st->execute();$d=$st->get_result()->fetch_assoc();if(!$d){http_response_code(404);exit('Data pendaftar tidak ditemukan.');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=$_POST['status']??'';$note=trim($_POST['catatan_admin']??'');$allowed=['Menunggu Verifikasi','Dalam Verifikasi','Lolos','Tidak Lolos'];if(!in_array($status,$allowed,true))$error='Status tidak valid.';else{$up=$conn->prepare("UPDATE pendaftar SET status=?,catatan_admin=? WHERE id=?");$up->bind_param('ssi',$status,$note,$id);$up->execute();header("Location: detail.php?id=$id&saved=1");exit;}}
?>
